function parseStatus(line){if(!activeGroup||lock!=='run')return false;const s=activeGroup.stages[cursor],key=s.config.session||activeGroup.id,frame=HC.readStatus(line,statusFrames.get(key));if(!frame)return false;statusFrames.set(key,frame);if(frame.done!=null){s.telemetry=frame;lastStatus=Date.now();}return true;}
