function refreshCheckpoints(){const paths=[...new Set(groups.flatMap(g=>g.stages.map(s=>HC.restorePath(s.args))).filter(Boolean))].slice(0,1000);if(paths.length)send('checkpoints',{id:++checkpointId,paths});}
function eligible(g){return !['found','queued','running'].includes(g.state)&&resumeStages(g).length>0;}
function resumeOptions(){return {...($('resumeRuntime').value==='keep'?{}:{runtime:$('resumeRuntime').value}),...($('resumeDeviceMode').value==='keep'?{}:{devices:$('resumeDevices').value.trim()})};}
function resumeStages(g){return g.stages.filter(s=>s.state==='pending'&&(!s.args.includes('--restore-position')||checkpoints.get(HC.restorePath(s.args))?.exists)||checkpoints.get(HC.restorePath(s.args))?.exists&&['stopped','limited','error','interrupted'].includes(s.state));}
