function updateResumePreview(){if(!resumeTarget)return;try{const options=resumeOptions();const commands=resumeStages(resumeTarget).map(s=>{const args=HC.resumeArgs(s.args,options,s.state!=='pending'||s.args.includes('--restore-position'));return HC.command($('engine').value,args,hostPlatform);});text('resumePreview',commands.join('\n\n'));text('resumeError','');$('confirmResume').disabled=!commands.length;}catch(e){text('resumeError',e.message);$('confirmResume').disabled=true;}}
