for(const id of ['closeResume','cancelResume'])$(id).onclick=()=>{$('resumeDialog').close();resumeTarget=null;};
$('resumeDialog').addEventListener('close',()=>{resumeTarget=null;});
$('resumeRuntime').onchange=updateResumePreview;$('resumeDevices').oninput=updateResumePreview;$('resumeDeviceMode').onchange=()=>{$('resumeDevices').disabled=$('resumeDeviceMode').value!=='custom';updateResumePreview();};
$('confirmResume').onclick=()=>{if(!resumeTarget||guarded())return;try{const g=resumeTarget,options=resumeOptions();for(const s of resumeStages(g)){HC.resumeArgs(s.args,options);if(g.kind==='guided')HC.validate({...s.config,...options,engine:$('engine').value});}workbench.resume(g,options);$('resumeDialog').close();resumeTarget=null;}catch(e){text('resumeError',e.message);}};
