function openGroup(g){inspection=-1;selectedGroup=g;resetMetrics();hide('outcomeCard',g.state==='running');text('outcomeTitle',stateNames[g.state]||g.state);text('outcomeNote','可以查看已恢复结果，或调整线索生成新的计划。继续检查点会沿用原来的范围与时间上限。');text('runStatus',stateNames[g.state]||g.state);text('runStateTag',stateNames[g.state]||g.state);text('runPurpose',g.format||'完整命令');text('heartbeat',g.state==='running'?'当前任务仍在本机运行':'历史任务未在计算中。');renderMonitor();page('monitor');busyUI();const last=g.stages.filter(s=>s.logPath).at(-1);if(last&&g.id!==activeGroup?.id)send('read_log',{id:g.id,path:last.logPath});if(g.kind==='guided'&&!['queued','running'].includes(g.state)&&!lock&&!sequence)queryResults(g);}
function renderRecent(){const box=$('recentTasks');box.replaceChildren();if(!groups.length){box.append(node('div','还没有任务。选择一个文件，开始第一次恢复。','empty'));return;}for(const g of groups.slice(0,3)){const b=node('button',undefined,'recent-row'),info=node('div');info.append(node('strong',HC.fileName(g.source||g.name)),node('small',g.name+' · '+new Date(g.created).toLocaleString()));b.append(node('span',g.kind==='raw'?'CMD':HC.fileName(g.source).split('.').pop().toUpperCase().slice(0,5),'file-type'),info,node('span',stateNames[g.state]||g.state,'tag'));b.onclick=()=>openGroup(g);box.append(b);}}
